const input = require("fs").readFileSync(0, "utf8");
const jobs = input.trim().split("\n").map((line) => {
  const [name, pagesText] = line.trim().split(/\s+/);
  return { name, pages: Number(pagesText) };
});

function runPrinter(jobs, perTurn) {
  const queue = [...jobs];
  let head = 0;
  let turns = 0;
  while (head < queue.length) {
    const job = queue[head++];
    const printed = Math.min(job.pages, perTurn);
    job.pages -= printed;
    turns++;
    console.log(`${job.name} prints ${printed} (${job.pages} left)`);
    if (job.pages > 0) {
      queue.push(job);
    }
  }
  return turns;
}

console.log(`done after ${runPrinter(jobs, 5)} turns`);

