  const [name, visitsText] = line.trim().split(/\s+/);
  return { name, visits: Number(visitsText) };
});

function serveOrder(customers) {
  const order = [];
  const queue = [...customers];
  let head = 0;
  while (head < queue.length) {
    const customer = queue[head++];
    order.push(customer.name);
    customer.visits--;
    if (customer.visits > 0) {
      queue.push(customer);
    }
  }
  return order;
}

