steps.body:
Breadth-first search (BFS) explores a grid in rings. It visits the start, then every cell 1 step away, then every cell 2 steps away, and so on. Cells come out of the queue in order of distance, so the first time BFS reaches the target, the distance it carries is the shortest path. DFS finds *a* path. BFS finds the *shortest* one.

Use an array as the queue and read it with a `head` index (`queue[head++]`), since `shift()` is O(n). Store each cell with its distance as a small tuple:

```javascript harness
const startRow = 0;
const startCol = 0;
let head = 0;
const nr = 0; // the neighbor to the right of the start
const nc = 1;
{{code}}
console.log(`queue: ${JSON.stringify(queue)}, head: ${head}`);
```

```javascript
const queue = [[startRow, startCol, 0]];
const [r, c, dist] = queue[head++];
queue.push([nr, nc, dist + 1]);
```

Mark a cell visited **when you enqueue it**, not when you dequeue it. Otherwise two neighbors can both push the same cell before either is processed, and the queue fills with duplicates. Keep visited in a boolean grid. A `Set` of `[r, c]` arrays never matches because arrays compare by reference.

If the queue runs dry before reaching the target, the target is walled off, so return -1.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const grid = input.trim().split("\n").map((line) => line.trim().split(""));
const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

function findCell(grid, mark) {
  for (let r = 0; r < grid.length; r++) {
    const c = grid[r].indexOf(mark);
    if (c !== -1) {
      return [r, c];
    }
  }
  return [-1, -1];
}

function shortestPath(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const [startRow, startCol] = findCell(grid, "S");
  const visited = Array.from({ length: rows }, () => new Array(cols).fill(false));
  const queue = [[startRow, startCol, 0]];
  visited[startRow][startCol] = true;
  let head = 0;
  while (head < queue.length) {
    const [r, c, dist] = queue[head++];
    if (grid[r][c] === "E") {
      return dist;
    }
    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;
      if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
        continue;
      }
      if (visited[nr][nc] || grid[nr][nc] === "#") {
        continue;
      }
      visited[nr][nc] = true;
      queue.push([nr, nc, dist + 1]);
    }
  }
  return -1;
}

console.log(`Shortest path: ${shortestPath(grid)}`);

